// Des: Load and check aa-conf-main.json, defaults if missing
// Flo: read file > parse JSON (unknown keys ignored) > check values > expand ~ in paths
// I/O: file path (aa-conf-main.json) > Conf struct (arena owned)
// ===================================================================
const std = @import("std"); const builtin = @import("builtin");
const CF = .{ .maxz = 65536, .tilz = '~' };
pub const Conf = struct { base_urlz_main: []const u8 = "https://www.oracle.com", base_appz_main: []const u8 = "https://cloud.oracle.com", base_docz_main: []const u8 = "https://docs.oracle.com", data_loca_wind: []const u8 = "E:\\.zz-base-home-tena\\as-apps\\in-inte\\or-orac-webs", data_loca_unix: []const u8 = "~/.zz-base-home-tena/as-apps/in-inte/or-orac-webs", secr_loca_main: []const u8 = "~/.zz-base-home-secr/as-apps/in-inte/or-orac-webs", brow_exec_path: []const u8 = "", brow_head_mode: bool = false, brow_time_seco: u32 = 60, brow_vers_minz: u32 = 120, type_dely_msec: [2]u32 = .{ 90, 260 }, acti_dely_secs: [2]u32 = .{ 2, 9 }, mous_step_coun: u32 = 18, time_scal_perc: u32 = 100, rand_seed_numb: u64 = 0, capz_acct_dayz: u32 = 10, capz_prod_dayz: u32 = 200, capz_data_dayz: u32 = 300, capz_mone_dayz: u32 = 5, capz_acce_dayz: u32 = 30, capz_sett_dayz: u32 = 30, capz_help_dayz: u32 = 30, quie_hour_rang: [2]u8 = .{ 0, 0 }, quie_zone_minu: i32 = 0, warm_dayz_coun: u32 = 0, retr_coun_maxz: u32 = 3, noti_chai_orde: []const []const u8 = &.{ "toas", "file" }, flow_list: []const FlowDef = &.{}, lang_main_code: []const u8 = "en", wait_maxx_secs: u32 = 0, wait_maxx_minu: u32 = 30, sett_wait_minu: u32 = 15, cool_hour_coun: u32 = 24, cool_perc_caps: u32 = 50, msgs_keep_days: u32 = 30, logz_body_enab: bool = false, labl_over: std.json.ArrayHashMap([]const []const u8) = .{}, path_over: std.json.ArrayHashMap([]const u8) = .{}, acct_maxx_coun: u32 = 3, acct_gap_secs: [2]u32 = .{ 300, 1200 } };
pub const JobRef = struct { job: []const u8, text: []const u8 = "", to: []const u8 = "", url: []const u8 = "", title: []const u8 = "", price: []const u8 = "", desc: []const u8 = "", group: []const u8 = "", photo: []const u8 = "", opt: []const u8 = "", date: []const u8 = "", time: []const u8 = "", catg: []const u8 = "", cond: []const u8 = "", loca: []const u8 = "", maxn: u32 = 5, acct: []const u8 = "" };
pub const FlowDef = struct { name: []const u8, jobs: []const JobRef };
pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err| { if (err == error.FileNotFound) return .{}; return err; }; return confParse(allo, byte); }
pub fn confParse(allo: std.mem.Allocator, byte: []const u8) !Conf { const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if (conf.type_dely_msec[0] > conf.type_dely_msec[1] or conf.type_dely_msec[0] == 0) return error.BadConfig; if (conf.acti_dely_secs[0] > conf.acti_dely_secs[1]) return error.BadConfig; if (conf.quie_hour_rang[0] > 23 or conf.quie_hour_rang[1] > 23) return error.BadConfig; if (conf.time_scal_perc > 1000 or conf.mous_step_coun == 0 or conf.mous_step_coun > 200) return error.BadConfig; if (conf.retr_coun_maxz == 0 or conf.retr_coun_maxz > 10 or conf.brow_time_seco == 0) return error.BadConfig; if (!std.mem.eql(u8, conf.lang_main_code, "en")) return error.BadConfig; if (conf.cool_perc_caps == 0 or conf.cool_perc_caps > 100 or conf.wait_maxx_minu == 0) return error.BadConfig; for (conf.noti_chai_orde) |ite| if (!std.mem.eql(u8, ite, "toas") and !std.mem.eql(u8, ite, "file")) return error.BadConfig; for (conf.flow_list) |fl| { if (fl.name.len == 0 or fl.jobs.len == 0) return error.BadConfig; } if (conf.quie_zone_minu < -840 or conf.quie_zone_minu > 840) return error.BadConfig; if (!std.mem.startsWith(u8, conf.base_urlz_main, "http") or !std.mem.startsWith(u8, conf.base_appz_main, "http")) return error.BadConfig; if (conf.acct_maxx_coun == 0 or conf.acct_maxx_coun > 20 or conf.acct_gap_secs[0] > conf.acct_gap_secs[1]) return error.BadConfig; }
pub fn dataDir(allo: std.mem.Allocator, home: []const u8, conf: Conf) ![]u8 { return pathExpa(allo, home, if (builtin.os.tag == .windows) conf.data_loca_wind else conf.data_loca_unix); }
pub fn subDir(allo: std.mem.Allocator, home: []const u8, conf: Conf, subz: []const u8) ![]u8 { const root = try dataDir(allo, home, conf); defer allo.free(root); return std.fs.path.join(allo, &.{ root, subz }); }
pub fn secrDir(allo: std.mem.Allocator, home: []const u8, conf: Conf) ![]u8 { return pathExpa(allo, home, conf.secr_loca_main); }
pub fn pathExpa(allo: std.mem.Allocator, home: []const u8, path: []const u8) ![]u8 { if (path.len > 0 and path[0] == CF.tilz) { if (home.len == 0) return error.BadConfig; return std.fmt.allocPrint(allo, "{s}{s}", .{ home, path[1..] }); } return allo.dupe(u8, path); }
